#!/usr/bin/env node
// Creates a local .env (git-ignored, mode 0600) with random demo role tokens.
// Never overwrites an existing .env.   Usage: npm run setup
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const file = path.resolve(import.meta.dirname, '../.env');
if (fs.existsSync(file)) {
  console.log('.env already exists; leaving it unchanged.');
  process.exit(0);
}
const token = () => crypto.randomBytes(32).toString('hex');
fs.writeFileSync(
  file,
  [
    '# Local demo secrets. Generated by scripts/setup-env.mjs. NEVER commit this file.',
    `ISSUER_API_TOKEN=${token()}`,
    `VERIFIER_API_TOKEN=${token()}`,
    '',
  ].join('\n'),
  { mode: 0o600 },
);
console.log(`Created ${file} with random ISSUER_API_TOKEN and VERIFIER_API_TOKEN (mode 0600).`);
